我来为你提供几段不同场景的Vega代码示例：

## 1. **简单柱状图**
```json
{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "width": 400,
  "height": 300,
  "padding": 20,

  "data": [
    {
      "name": "table",
      "values": [
        {"category": "A", "value": 28},
        {"category": "B", "value": 55},
        {"category": "C", "value": 43},
        {"category": "D", "value": 91},
        {"category": "E", "value": 81}
      ]
    }
  ],

  "scales": [
    {
      "name": "xscale",
      "type": "band",
      "domain": {"data": "table", "field": "category"},
      "range": "width",
      "padding": 0.2
    },
    {
      "name": "yscale",
      "type": "linear",
      "domain": {"data": "table", "field": "value"},
      "range": "height",
      "nice": true
    }
  ],

  "axes": [
    {"orient": "bottom", "scale": "xscale", "title": "分类"},
    {"orient": "left", "scale": "yscale", "title": "数值"}
  ],

  "marks": [
    {
      "type": "rect",
      "from": {"data": "table"},
      "encode": {
        "enter": {
          "x": {"scale": "xscale", "field": "category"},
          "width": {"scale": "xscale", "band": 1},
          "y": {"scale": "yscale", "field": "value"},
          "y2": {"scale": "yscale", "value": 0},
          "fill": {"value": "#4c78a8"}
        }
      }
    }
  ]
}
```

## 2. **折线图和散点图组合**
```json
{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "width": 500,
  "height": 400,
  "padding": 30,

  "data": [
    {
      "name": "points",
      "values": [
        {"x": 1, "y": 5, "group": "A"},
        {"x": 2, "y": 7, "group": "A"},
        {"x": 3, "y": 6, "group": "A"},
        {"x": 4, "y": 8, "group": "A"},
        {"x": 1, "y": 8, "group": "B"},
        {"x": 2, "y": 6, "group": "B"},
        {"x": 3, "y": 9, "group": "B"},
        {"x": 4, "y": 7, "group": "B"}
      ]
    }
  ],

  "scales": [
    {
      "name": "xscale",
      "type": "linear",
      "domain": [0, 5],
      "range": "width"
    },
    {
      "name": "yscale",
      "type": "linear",
      "domain": [0, 10],
      "range": "height"
    },
    {
      "name": "color",
      "type": "ordinal",
      "domain": ["A", "B"],
      "range": ["#e45756", "#72b7b2"]
    }
  ],

  "axes": [
    {"orient": "bottom", "scale": "xscale", "title": "X轴"},
    {"orient": "left", "scale": "yscale", "title": "Y轴"}
  ],

  "legends": [
    {"fill": "color", "title": "分组"}
  ],

  "marks": [
    {
      "type": "group",
      "from": {
        "facet": {
          "name": "series",
          "data": "points",
          "groupby": "group"
        }
      },
      "marks": [
        {
          "type": "line",
          "from": {"data": "series"},
          "encode": {
            "enter": {
              "x": {"scale": "xscale", "field": "x"},
              "y": {"scale": "yscale", "field": "y"},
              "stroke": {"scale": "color", "field": "group"},
              "strokeWidth": {"value": 2}
            }
          }
        },
        {
          "type": "symbol",
          "from": {"data": "series"},
          "encode": {
            "enter": {
              "x": {"scale": "xscale", "field": "x"},
              "y": {"scale": "yscale", "field": "y"},
              "fill": {"scale": "color", "field": "group"},
              "size": {"value": 100}
            }
          }
        }
      ]
    }
  ]
}
```

## 3. **饼图**
```json
{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "width": 400,
  "height": 400,

  "data": [
    {
      "name": "table",
      "values": [
        {"id": 1, "category": "电子产品", "value": 35},
        {"id": 2, "category": "服装", "value": 25},
        {"id": 3, "category": "食品", "value": 20},
        {"id": 4, "category": "书籍", "value": 15},
        {"id": 5, "category": "其他", "value": 5}
      ]
    }
  ],

  "scales": [
    {
      "name": "color",
      "type": "ordinal",
      "domain": {"data": "table", "field": "category"},
      "range": ["#98abc5", "#8a89a6", "#7b6888", "#6b486b", "#a05d56"]
    }
  ],

  "marks": [
    {
      "type": "arc",
      "from": {"data": "table"},
      "encode": {
        "enter": {
          "x": {"signal": "width / 2"},
          "y": {"signal": "height / 2"},
          "startAngle": {"field": "startAngle"},
          "endAngle": {"field": "endAngle"},
          "innerRadius": {"value": 50},
          "outerRadius": {"signal": "width / 2 - 40"},
          "fill": {"scale": "color", "field": "category"}
        }
      }
    },
    {
      "type": "text",
      "from": {"data": "table"},
      "encode": {
        "enter": {
          "x": {"signal": "width / 2 + 150 * cos((datum.startAngle + datum.endAngle)/2)"},
          "y": {"signal": "height / 2 + 150 * sin((datum.startAngle + datum.endAngle)/2)"},
          "text": {"field": "category"},
          "baseline": {"value": "middle"},
          "align": {"signal": "datum.startAngle + datum.endAngle < PI ? 'left' : 'right'"},
          "fontSize": {"value": 14}
        }
      }
    }
  ],

  "signals": [
    {
      "name": "pie",
      "value": {},
      "update": "pie({field: 'value'})"
    }
  ],

  "transform": [
    {
      "type": "pie",
      "field": "value"
    }
  ]
}
```

## 使用方法：
1. 复制上述任一代码
2. 访问 [Vega Editor](https://vega.github.io/editor/)
3. 粘贴代码运行即可看到可视化效果

